insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_110_v1'
from (values
('127.802.d.3',3,'A city intern learns that officials must avoid using their positions for personal gain, must disclose conflicts of interest and must treat residents fairly. She is exploring:','["government ethics", "park design", "budget printing", "traffic engineering"]'::jsonb,0,'Ethics guide public service.','original'),
('127.802.d.3',4,'A council member''s brother bids on a city contract. The most ethical step for the council member is to:','["vote quietly for the bid", "disclose the conflict and step out of the decision", "lobby colleagues", "hide the relationship"]'::jsonb,1,'Disclosure and recusal avoid conflicts.','original'),
('127.802.d.1.A',3,'A civics club reads Plato on justice, Aristotle on forms of government and Machiavelli on power to compare early ideas about rule. They are reviewing the works of:','["chefs", "modern pop singers", "classical political theorists", "sports coaches"]'::jsonb,2,'Early theorists shaped political thought.','original'),
('127.802.d.1.A',4,'Aristotle is best known in political thought for:','["designing the Constitution", "inventing paper money", "writing the Bill of Rights", "classifying governments and studying their strengths"]'::jsonb,3,'Aristotle compared constitutions.','original'),
('127.802.d.1.B',3,'A student traces how Locke''s ideas about natural rights and consent of the governed appear in modern democracies. She is analyzing:','["contributions of classical theorists to modern political science", "changes in fashion", "growth of cities", "trends in music"]'::jsonb,0,'Locke influenced modern ideas of rights.','original'),
('127.802.d.1.B',4,'The idea that a government''s power comes from the consent of the people is most associated with:','["a medieval baron", "Locke", "Hobbes'' absolute monarch alone", "Machiavelli"]'::jsonb,1,'Locke argued for consent of the governed.','original'),
('127.802.d.2.A',3,'A class reviews the Articles of Confederation, the Constitution''s separation of powers and the first ten amendments to see how the founders organized government. They are reviewing:','["state fair rules", "school bus routes", "basic information related to the U.S. Constitution", "sports brackets"]'::jsonb,2,'The Constitution organizes government.','original'),
('127.802.d.2.A',4,'The first ten amendments to the U.S. Constitution are called the:','["Federalist Papers", "Magna Carta", "Articles of Confederation", "Bill of Rights"]'::jsonb,3,'The Bill of Rights protects liberties.','original'),
('127.802.d.2.B',3,'Students write articles for a classroom government with three branches and a list of student rights, then hold a mock ratification vote. They are creating a:','["classroom Constitution and Bill of Rights", "school yearbook", "class schedule", "lunch menu"]'::jsonb,0,'Simulation builds understanding.','original'),
('127.802.d.2.B',4,'A classroom Constitution that divides power between a rules group, an enforcement group and a judging group illustrates:','["a single ruler", "separation of powers", "a monarchy", "anarchy"]'::jsonb,1,'Three branches share power.','original'),
('127.802.d.4.A',3,'An intern is asked to look into why a city''s permit approvals take so long and whether a new online system is feasible. She begins by researching:','["a menu change", "a prom theme", "a government and public administration issue", "a movie review"]'::jsonb,2,'Research starts with a real problem.','original'),
('127.802.d.4.A',4,'A feasibility study asks whether a proposed project is:','["colorful", "short", "popular on social media", "practical and workable given time, money and resources"]'::jsonb,3,'Feasibility tests practicality.','original'),
('127.802.d.4.B',3,'After choosing the permit delay issue, the intern interviews staff, reviews the application steps and checks how other cities handle it. She is:','["investigating the issues associated with the problem", "guessing causes", "ignoring the problem", "skipping research"]'::jsonb,0,'Investigate causes before proposing.','original'),
('127.802.d.4.B',4,'A good way to find the causes of a long permit process is to:','["assume staff are lazy", "map each step and note where applications wait", "copy another city exactly", "skip the data"]'::jsonb,1,'Process mapping reveals bottlenecks.','original'),
('127.802.d.4.C',3,'The intern surveys residents about how long their permit took and observes the counter staff for two mornings. She is collecting:','["fiction stories", "secondary data from a textbook", "primary data such as interviews, surveys and observations", "recipes"]'::jsonb,2,'Primary data comes first-hand.','original'),
('127.802.d.4.C',4,'Data an intern gathers herself through a survey is called:','["secondary data", "random data", "borrowed data", "primary data"]'::jsonb,3,'Collected directly.','original'),
('127.802.d.4.D',3,'In her report, the intern states the problem, then her method, then findings and recommendations in a clear order. She is:','["expressing thoughts logically and sequentially in a formal report", "writing a poem", "drawing a map", "writing a random list"]'::jsonb,0,'Reports follow a logical order.','original'),
('127.802.d.4.D',4,'A formal report usually ends with:','["a random fact", "conclusions and recommendations based on the findings", "a new topic", "a joke"]'::jsonb,1,'Recommendations close a report.','original'),
('127.802.d.4.E',3,'The intern turns her survey results into a bar graph showing average wait times by permit type. She is:','["writing a story", "copying a table", "interpreting and presenting quantitative data in graph format", "avoiding numbers"]'::jsonb,2,'Graphs make data clear.','original'),
('127.802.d.4.E',4,'A bar graph is most useful for:','["hiding data", "listing names", "showing a story", "comparing amounts across categories"]'::jsonb,3,'Bars compare categories.','original'),
('127.802.d.4.F',3,'Before her briefing, the intern prepares slides with key charts and a one-page handout summarizing her recommendations. She is preparing:','["visuals and handouts to support the presentation", "a game schedule", "a travel plan", "a party menu"]'::jsonb,0,'Visuals help the audience follow.','original'),
('127.802.d.4.F',4,'A handout is most effective when it:','["repeats every detail", "summarizes the key points on one clear page", "has tiny print", "has no title"]'::jsonb,1,'Concise handouts help.','original'),
('127.802.d.4.G',3,'The intern presents her findings and recommendations to the department director and a council member and answers their questions. She is making a:','["private diary entry", "social post", "final presentation of the study to the appropriate stakeholders", "casual chat"]'::jsonb,2,'Stakeholders hear the findings.','original'),
('127.802.d.4.G',4,'Stakeholders are people who:','["only own businesses", "are all strangers", "only work for the city", "are affected by or have an interest in the outcome"]'::jsonb,3,'Stakeholders have a stake.','original'),
('127.802.d.5.A',3,'A student adds her certificates, a letter of recommendation, a scholarship notice and a sample report to a binder that shows her accomplishments. She is updating a:','["professional portfolio with recognitions, awards and scholarships", "game library", "scrapbook of jokes", "playlist"]'::jsonb,0,'Portfolios collect achievements.','original'),
('127.802.d.5.A',4,'A work sample in a portfolio should show:','["only a title page", "the quality of the student''s own work", "only a list of hobbies", "only photos of friends"]'::jsonb,1,'Samples demonstrate skill.','original'),
('127.802.d.5.B',3,'At the end of her practicum, a student walks a panel of local officials through her portfolio and explains how each piece reflects her skills. She is:','["reading a menu", "hiding her work", "presenting the portfolio to interested stakeholders", "quitting early"]'::jsonb,2,'Share and explain.','original'),
('127.802.d.5.B',4,'When presenting a portfolio to officials, a student should:','["read every word silently", "avoid questions", "skip the samples", "explain what each piece shows and what she learned"]'::jsonb,3,'Connect work to skills.','original'),
('127.803.d.1.A',3,'An intern calls a resident to explain a new recycling rule in short, plain sentences and checks that the resident understood. This is:','["clear, concise and accurate verbal communication", "using technical jargon only", "speaking too fast to follow", "rambling"]'::jsonb,0,'Be clear.','original'),
('127.803.d.1.B',3,'After a public meeting, a trainee summarizes the key votes, dates and public comments in a short memo for her supervisor. She is:','["guessing the votes", "analyzing and communicating information, data and observations", "skipping the memo", "hiding the notes"]'::jsonb,1,'Summaries inform decisions.','original'),
('127.803.d.1.C',3,'An intern leads a brief team update at the office and later gives a longer slide presentation at a community meeting. She is delivering:','["private notes", "email only", "formal and informal presentations", "only written reports"]'::jsonb,2,'Both informal and formal speaking matter.','original'),
('127.803.d.1.C',4,'A formal presentation is usually:','["unprepared", "spontaneous", "anonymous", "planned with an organized structure and visuals"]'::jsonb,3,'Formal means prepared.','original'),
('127.803.d.1.D',3,'A trainee at a front counter notices a visitor''s furrowed brow and slow speech and offers to repeat the instructions. She is:','["observing and interpreting verbal and nonverbal cues", "rushing", "guessing", "ignoring the visitor"]'::jsonb,0,'Cues show understanding.','original'),
('127.803.d.2.A',3,'A team at city hall is asked to reduce wait times at the licensing counter. Each member studies the process independently and then they combine ideas. They are employing:','["imitation", "critical-thinking skills independently and in a team", "avoidance", "chance"]'::jsonb,1,'Critical thinking applies to problems.','original'),
('127.803.d.2.A',4,'When tackling a recurring office problem, a team should begin by:','["assuming the cause", "dropping the issue", "gathering facts about what is actually happening", "assigning blame"]'::jsonb,2,'Facts first.','original'),
('127.803.d.2.B',3,'A trainee breaks a mailroom backlog into causes such as late pickups and unclear labels, then proposes a new sorting step. She is:','["denying the backlog", "ignoring the causes", "blaming the mail carrier", "analyzing elements of a problem to develop creative and innovative solutions"]'::jsonb,3,'Analyze, then create.','original'),
('127.803.d.3.A',3,'A practicum student arrives on time, completes each filing assignment as directed and asks for more work when finished. She is demonstrating:','["a positive, productive work ethic", "avoidance", "entitlement", "laziness"]'::jsonb,0,'Work ethic shows reliability.','original'),
('127.803.d.3.A',4,'Which habit best reflects a productive work ethic at a government office?','["waiting to be reminded", "completing assigned tasks fully and on schedule", "leaving early", "doing the minimum"]'::jsonb,1,'Productive effort.','original'),
('127.803.d.3.B',3,'A clerk sees that a friend''s permit form is incomplete. Showing integrity, she:','["fills it in secretly", "approves it anyway", "asks the friend to complete it like anyone else", "hides it"]'::jsonb,2,'Integrity means fairness.','original'),
('127.803.d.3.B',4,'Integrity means choosing the ethical course of action:','["only when watched", "only for rewards", "only for friends", "even when no one is watching"]'::jsonb,3,'Integrity is internal.','original'),
('127.803.d.3.C',3,'An intern is tempted to skip a required records check to meet a deadline but follows the rule anyway. She is:','["complying with all applicable rules, laws and regulations consistently", "skipping steps", "ignoring regulations", "bending rules for speed"]'::jsonb,0,'Follow the rules every time.','original'),
('127.803.d.4.A',3,'An intern leads a short civic awareness activity at a library, keeps a log of what she did and writes a reflection on its results. She is:','["ignoring feedback", "conducting, documenting and evaluating learning activities in a supervised setting", "working without records", "avoiding supervision"]'::jsonb,1,'Do, document and evaluate.','original'),
('127.803.d.4.B',3,'An intern studies whether a city should switch to online forms, comparing costs, time savings and resident needs. She is completing a:','["game schedule", "menu review", "feasibility study", "poetry reading"]'::jsonb,2,'Feasibility tests workability.','original'),
('127.803.d.4.B',4,'A product evaluation compares a product''s features against:','["its brand name only", "its box design", "its color only", "the needs and standards it is supposed to meet"]'::jsonb,3,'Evaluate against needs.','original'),
('127.803.d.4.C',3,'For her study, an intern interviews three department heads, surveys residents and observes a public counter for a day. She is collecting:','["primary data", "fiction", "guesses", "rumors"]'::jsonb,0,'First-hand data.','original'),
('127.803.d.4.C',4,'Interviews, surveys and observations are examples of:','["opinions only", "primary data collection methods", "secondary sources", "entertainment"]'::jsonb,1,'They gather original data.','original'),
('127.803.d.4.D',3,'An intern calculates the average wait time from her observation data and shows it in a chart for the director. She is:','["hiding the results", "guessing", "interpreting and presenting quantitative data", "ignoring numbers"]'::jsonb,2,'Quantitative data uses numbers.','original'),
('127.803.d.4.D',4,'The average of 10, 20 and 30 minutes is:','["10 minutes", "60 minutes", "30 minutes", "20 minutes"]'::jsonb,3,'(10+20+30)/3 = 20.','original'),
('127.803.d.4.E',3,'After a mock budget exercise, an intern notes that she is strong at spreadsheets but needs practice explaining numbers aloud. She is:','["evaluating strengths and weaknesses in technical skill proficiency", "boasting", "ignoring feedback", "hiding results"]'::jsonb,0,'Self-evaluation guides growth.','original'),
('127.803.d.4.F',3,'At the end of her practicum, a student saves a sample memo, a presentation and a supervisor''s evaluation in a folder. She is:','["avoiding evidence", "collecting representative work samples", "copying others'' work", "tossing records"]'::jsonb,1,'Work samples show ability.','original'),
('127.803.d.4.F',4,'Work samples are useful in a job search because they:','["replace interviews", "hide weaknesses", "show employers actual examples of your skills", "avoid references"]'::jsonb,2,'Samples prove ability.','original'),
('127.803.d.4.A',4,'Keeping a learning log during a supervised practicum helps because it:','["hides mistakes", "replaces supervision", "avoids evaluation", "records activities and reflections that show growth"]'::jsonb,3,'Logs document learning.','original'),
('127.803.d.4.E',4,'Honest self-evaluation of skill proficiency allows a trainee to:','["focus practice on areas that need improvement", "avoid feedback", "skip training", "hide errors"]'::jsonb,0,'Targeted practice.','original'),
('127.803.d.1.A',4,'In a phone call with a resident, the best way to confirm understanding is to:','["talk faster", "ask the resident to restate the key steps", "change the subject", "hang up politely"]'::jsonb,1,'Confirm understanding.','original'),
('127.803.d.1.B',4,'A short memo that summarizes a meeting should include:','["unrelated stories", "personal opinions only", "key decisions, dates and next steps", "jokes"]'::jsonb,2,'Memos capture actions.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_110_v1'
from (values
('127.803.d.1.D',4,'A crossed-arm stance and short answers may signal that a visitor is:','["relaxed", "very happy", "asleep", "uncomfortable or unconvinced"]'::jsonb,3,'Nonverbal cues convey feelings.','original'),
('127.803.d.2.B',4,'After identifying the causes of a problem, a team should next:','["brainstorm and compare possible solutions", "pick the first idea", "cancel the project", "ignore the cause"]'::jsonb,0,'Generate options.','original'),
('127.803.d.3.C',4,'If a rule seems inconvenient, a public employee should:','["ignore it quietly", "follow it and raise concerns through proper channels", "break it once", "change it alone"]'::jsonb,1,'Follow rules; use channels.','original'),
('127.810.d.1.A',3,'A student compares a team that designs a new gear with a team that studies the metal''s strength, a team that mass-produces the gear and a team that builds the machine''s electronics. She is distinguishing among:','["history, law, civics and economics", "sports, travel, cooking and farming", "engineering, science, manufacturing and technology disciplines", "music, art, drama and dance"]'::jsonb,2,'Disciplines have different roles.','original'),
('127.810.d.1.A',4,'The discipline most directly focused on turning raw materials into finished products at scale is:','["art history", "journalism", "astronomy", "manufacturing"]'::jsonb,3,'Manufacturing makes products.','original'),
('127.810.d.1.B',3,'A shop student uses a calculator to find the area of a steel plate and a computer program to chart defects by day. She is using:','["tools such as calculators and computers to solve problems", "only a pencil", "only memory", "only hand guesses"]'::jsonb,0,'Tools speed accurate solutions.','original'),
('127.810.d.1.B',4,'A spreadsheet is most useful in a plant for:','["painting walls", "tracking and calculating production data", "drilling holes", "welding seams"]'::jsonb,1,'Spreadsheets organize data.','original'),
('127.810.d.1.C',3,'A technician checks a shaft with a micrometer, a plate with a caliper and a board with a tape measure, choosing each tool for the size and accuracy needed. He is using:','["only a thermometer", "only a stopwatch", "a variety of measuring instruments", "only a scale"]'::jsonb,2,'Different tools suit different measurements.','original'),
('127.810.d.1.C',4,'For measuring a very small diameter to a thousandth of an inch, the best tool is a:','["protractor", "tape measure", "yardstick", "micrometer"]'::jsonb,3,'Micrometers are precise.','original'),
('127.810.d.2.A',3,'A line lead explains a change to the shift in clear terms, uses standard drawing symbols and confirms everyone understands before starting. She is demonstrating:','["communication techniques consistent with industry standards", "guesses", "silence", "rumor-passing"]'::jsonb,0,'Clear standard communication prevents errors.','original'),
('127.810.d.2.A',4,'In manufacturing, a drawing with standardized symbols helps because it:','["hides details", "lets different workers read the same instructions the same way", "makes parts heavier", "replaces tools"]'::jsonb,1,'Standard symbols prevent confusion.','original'),
('127.810.d.2.B',3,'When a machine keeps jamming, an operator checks the manual, the maintenance log and the supplier''s spec sheet to find the cause. He is:','["blaming a coworker", "guessing", "locating relevant information needed to solve problems", "ignoring the jam"]'::jsonb,2,'Find facts before fixing.','original'),
('127.810.d.2.B',4,'The best first source for how to troubleshoot a specific machine is usually its:','["neighbor", "advertisement", "random web post", "operator or maintenance manual"]'::jsonb,3,'Manuals are authoritative.','original'),
('127.810.d.2.C',3,'A worker cuts a 96-inch board into equal pieces 12 inches long and then calculates how many pieces fit. He is applying:','["mathematics concepts to solve manufacturing problems", "cooking methods", "dance steps", "art techniques"]'::jsonb,0,'Division finds the count.','original'),
('127.810.d.2.C',4,'How many 12-inch pieces can be cut from a 96-inch board, ignoring waste?','["6", "8", "9", "12"]'::jsonb,1,'96 ÷ 12 = 8.','original'),
('127.810.d.2.D',3,'Engineers explain that a longer wrench handle makes a stuck bolt easier to turn because it provides a longer lever arm. They are analyzing:','["menu ideas", "fashion trends", "science principles used to solve problems", "sports scores"]'::jsonb,2,'Levers multiply force.','original'),
('127.810.d.2.D',4,'A simple machine that makes work easier by reducing the force needed over a longer distance is a:','["thermometer", "calculator", "clock", "lever"]'::jsonb,3,'Levers are simple machines.','original'),
('127.810.d.2.E',3,'A technician records the length of a part as 2.5 meters and the mass of a batch as 40 kilograms, not mixing in inches or ounces. He is using:','["the appropriate units of measure", "no units", "random units", "mixed units"]'::jsonb,0,'Consistent units prevent errors.','original'),
('127.810.d.2.E',4,'A batch''s mass should be recorded in:','["inches", "kilograms or pounds with the unit written", "degrees", "gallons"]'::jsonb,1,'Mass uses mass units.','original'),
('127.810.d.3.A',3,'A small team starts a project by defining the goal, then makes a schedule, then builds the product, then checks it and finally reviews the results. They are analyzing the processes needed to complete a project such as:','["buy, sell, borrow and lend", "wake, eat, sleep and play", "initiate, plan, execute, monitor and close", "start, stop, start and stop"]'::jsonb,2,'Project phases.','original'),
('127.810.d.3.A',4,'The phase of a project in which the work is actually carried out is called:','["initiation", "planning only", "closure", "execution"]'::jsonb,3,'Execute = do the work.','original'),
('127.810.d.3.B',3,'To produce a small wooden toy, students use a saw, a drill and a sander, following the cut list. They are using:','["a variety of tools and equipment to produce an item", "no tools", "only paper", "only hands"]'::jsonb,0,'Choose tools for the task.','original'),
('127.810.d.3.B',4,'Before using a power tool in the shop, a student should first:','["skip eye protection", "check that guards are in place and wear eye protection", "remove the guard", "start without checking"]'::jsonb,1,'Safety checks first.','original'),
('127.810.d.4.A',3,'Before entering the shop, a student must pass a test on machine guarding, protective gear and hazard reporting based on Occupational Safety and Health Administration rules. She is mastering:','["a music quiz", "a geography quiz", "relevant safety tests based on OSHA guidelines and principles", "a spelling test"]'::jsonb,2,'OSHA sets workplace safety rules.','original'),
('127.810.d.4.A',4,'OSHA is the federal agency responsible for:','["postal delivery", "college sports", "weather reports", "workplace safety and health standards"]'::jsonb,3,'OSHA protects workers.','original'),
('127.810.d.4.B',3,'A worker reads a Material Safety Data Sheet to learn how to store a solvent, what protective gear to use and how to dispose of it. She is using it to:','["analyze, store and safely dispose of hazardous materials", "order lunch", "decorate the shop", "play a game"]'::jsonb,0,'MSDS describe chemical hazards.','original'),
('127.810.d.4.B',4,'A safety data sheet tells a worker:','["the supplier''s logo", "a chemical''s hazards and how to handle it safely", "the color of the box", "the price of the chemical"]'::jsonb,1,'Safety info first.','original'),
('127.810.d.5.A',3,'A technician follows a checklist to lubricate a conveyor, tighten bolts and replace a worn belt. He is performing:','["decoration", "packaging", "maintenance on selected equipment", "marketing"]'::jsonb,2,'Preventive maintenance.','original'),
('127.810.d.5.A',4,'Regular lubrication of machine parts mainly helps to:','["make parts rust", "increase noise", "slow production", "reduce wear and prevent breakdowns"]'::jsonb,3,'Lubrication reduces friction.','original'),
('127.810.d.5.B',3,'A plant skips oil changes on a press, and the machine seizes and stops production for two days. Students analyze this as the result of:','["improper maintenance", "a planned upgrade", "good planning", "too much safety"]'::jsonb,0,'Neglect causes failure.','original'),
('127.810.d.5.B',4,'One likely result of improper maintenance is:','["lower costs", "unexpected downtime and higher repair costs", "longer machine life", "fewer defects"]'::jsonb,1,'Poor maintenance costs more.','original'),
('127.810.d.6.A',3,'A plant adds robotic arms to a line that once used hand assembly, which speeds production and changes the skills workers need. Students are analyzing how:','["weather affects crops", "music affects mood", "changes in technology affect manufacturing practices", "sports affect health"]'::jsonb,2,'Technology changes work.','original'),
('127.810.d.6.A',4,'One effect of automation on a factory floor is that:','["machines never break", "all jobs disappear", "no skills are needed", "fewer repetitive tasks are done by hand and new technical jobs appear"]'::jsonb,3,'Automation changes jobs.','original'),
('127.810.d.6.B',3,'A class studies how the invention of the steam engine, electricity and computers each changed how factories run. They are evaluating how:','["technology development is influenced by past events and discoveries", "a poem is rhymed", "a game is scored", "a menu is written"]'::jsonb,0,'Past innovations build future ones.','original'),
('127.810.d.6.B',4,'The assembly line, popularized in the early 1900s, changed manufacturing by:','["eliminating factories", "allowing products to be made faster and more cheaply", "slowing production", "ending car making"]'::jsonb,1,'Assembly line efficiency.','original'),
('127.810.d.6.C',3,'A student explains how a product designed in one country can be made in another and shipped around the world, affecting jobs and prices. She is analyzing:','["a local bake sale", "a one-room office", "the international effects of technology", "a school dance"]'::jsonb,2,'Technology links global markets.','original'),
('127.810.d.6.C',4,'One international effect of improved shipping and communication technology is:','["isolated factories", "no trade", "fewer products", "global supply chains that connect distant producers"]'::jsonb,3,'Supply chains span countries.','original'),
('127.810.d.6.D',3,'Engineers now test new aircraft parts with computer simulations and 3D printers before building them, saving time and money. This demonstrates how advancements in technology have affected:','["the field of engineering", "the field of sports", "the field of gardening", "the field of fashion"]'::jsonb,0,'Technology reshapes engineering.','original'),
('127.810.d.6.D',4,'Computer-aided design allows engineers to:','["avoid drawings", "create and test designs digitally before building", "skip testing", "draw only by hand"]'::jsonb,1,'CAD speeds design.','original'),
('127.810.d.6.E',3,'A company wants to adopt a new machine, but it costs a lot, requires training and may disrupt output at first. Students are evaluating:','["lunch plans", "parking spaces", "the factors that affect the implementation of new ideas", "room colors"]'::jsonb,2,'Cost, training and disruption matter.','original'),
('127.810.d.6.E',4,'A factor that can slow adoption of a new technology in a plant is:','["a short commute", "a clean floor", "a sunny day", "the cost and the time needed for worker training"]'::jsonb,3,'Cost and training are barriers.','original'),
('127.810.d.7.A',3,'A student interested in making things researches careers at a local plant, reads job descriptions and talks to a worker. She is:','["investigating an area of interest in manufacturing", "watching a movie", "playing a game", "skipping class"]'::jsonb,0,'Explore interests.','original'),
('127.810.d.7.A',4,'A good way to learn what a manufacturing job is really like is to:','["guess", "job-shadow or interview a worker", "avoid the plant", "read nothing"]'::jsonb,1,'Firsthand exposure helps.','original'),
('127.810.d.7.B',3,'A chart lists fabrication, machining, assembly, quality control and logistics as separate areas within one plant. Students are analyzing the various:','["genres in music", "positions on a team", "specializations in manufacturing", "species in a pond"]'::jsonb,2,'Plants have many specialties.','original'),
('127.810.d.7.B',4,'A specialist who inspects finished parts for defects works in:','["marketing", "payroll", "landscaping", "quality control"]'::jsonb,3,'Quality control checks products.','original'),
('127.810.d.7.C',3,'A plant manager explains that the engineer designs the process, the technologist helps put it into practice and the technician maintains the equipment. Students are describing:','["the functions of engineers, technologists and technicians", "the roles of chefs", "the work of artists", "the jobs of coaches"]'::jsonb,0,'Distinct but related roles.','original'),
('127.810.d.7.C',4,'Compared with an engineer, a technician typically focuses more on:','["teaching classes", "installing, operating and maintaining equipment", "inventing new theories", "writing laws"]'::jsonb,1,'Technicians work hands-on.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
